'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies } = require('./src/semver');

// caret on zero majors
assert.equal(satisfies('0.3.9', '^0.2.0'), false);
assert.equal(satisfies('0.2.9', '^0.2.0'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);

// backtracking must undo constraints of the abandoned choice
const reg1 = {
  a: { '2.0.0': { c: '1.0.0' }, '1.0.0': {} },
  b: { '1.0.0': { c: '2.0.0' } },
  c: { '1.0.0': {}, '2.0.0': {} },
};
assert.deepEqual(resolve(reg1, { a: '*', b: '*' }), { a: '1.0.0', b: '1.0.0', c: '2.0.0' });

// cycle
const reg2 = { x: { '1.0.0': { y: '^1.0.0' } }, y: { '1.0.0': { x: '1.0.0' } } };
assert.deepEqual(resolve(reg2, { x: '*' }), { x: '1.0.0', y: '1.0.0' });

// conflict
assert.equal(resolve({ p: { '1.0.0': { q: '2.0.0' } }, q: { '1.0.0': {} } }, { p: '*' }), null);
assert.equal(resolve({}, { missing: '*' }), null);
assert.deepEqual(resolve({}, {}), {});

// long chain with backtracking at the end
const N = 20000;
const reg3 = {};
for (let i = 0; i < N; i += 1) reg3['n' + i] = { '1.0.0': { ['n' + (i + 1)]: '*' } };
reg3['n' + N] = { '2.0.0': { n0: '2.0.0' }, '1.0.0': {} };
const r = resolve(reg3, { n0: '*' });
assert.equal(r['n' + N], '1.0.0');
assert.equal(Object.keys(r).length, N + 1);

// validation of unreachable entries
assert.throws(() => resolve({ z: { '1.0': {} } }, {}), TypeError);
assert.throws(() => resolve({ z: { '1.0.0': { w: '' } } }, {}), TypeError);
console.log('ok');
